#!/usr/bin/env python3
"""Deterministic Android wrappers/catalog. Never generates or edits artwork, never fakes a missing season."""
from pathlib import Path
import json,argparse,re
from seasonal_image import image_size
ROOT=Path(__file__).resolve().parents[1];RES=ROOT/'TMessagesProj/src/main/res';INPUT=ROOT/'assets/launcher/seasonal'
p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');args=p.parse_args()
catalog=json.loads((INPUT/'catalog.json').read_text());outputs={};available=[];missing=[];aliases=[];drawables=[];cases=[]
for key,legacy in catalog.items():
 brand='tetogram' if key.startswith('Tetogram') else 'mikugram';season=key.removeprefix('Tetogram').removeprefix('Mikugram').lower();name=f'{brand}_{season}'
 incoming_files=[INPUT/(name+suffix) for suffix in ('.png','.jpg','.jpeg') if (INPUT/(name+suffix)).is_file()]
 assert len(incoming_files)<=1,f'{name}: keep only one prepared source format'
 incoming=incoming_files[0] if incoming_files else INPUT/(name+'.png')
 canonical_files=[RES/'drawable-nodpi'/(name+suffix) for suffix in ('.png','.jpg','.jpeg') if (RES/'drawable-nodpi'/(name+suffix)).is_file()]
 assert len(canonical_files)<=1,f'{name}: duplicate Android resources'
 canonical=RES/'drawable-nodpi'/(name+incoming.suffix) if incoming.is_file() else canonical_files[0] if canonical_files else RES/'drawable-nodpi'/(name+'.png')
 if incoming.is_file() and canonical_files:assert canonical_files[0]==canonical,f'{name}: remove the previous generated format before changing it'
 fallback=RES/'drawable-nodpi'/(str(legacy)+'.png')
 source=incoming if incoming.is_file() else canonical if canonical.is_file() else fallback if legacy and fallback.is_file() else None
 if source:
  data=source.read_bytes();w,h=image_size(data);assert w==h and 256<=w<=8192,f'{name}: square prepared PNG/JPEG (256..8192px) required'
  if source==incoming:outputs[canonical]=data
  reference=name if source in (incoming,canonical) else legacy
  if reference!=name:drawables.append(f'    <drawable name="{name}">@drawable/{reference}</drawable>')
  available.append(key);cases.append(f'   case "{key}":return R.drawable.{name};')
  outputs[RES/'mipmap-anydpi-v26'/(name+'.xml')]=f'<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android"><background android:drawable="@android:color/black"/><foreground><inset android:insetLeft="28.5%" android:insetTop="28.5%" android:insetRight="28.5%" android:insetBottom="28.5%" android:drawable="@drawable/{name}"/></foreground></adaptive-icon>\n'
  outputs[RES/'mipmap-anydpi'/(name+'.xml')]=f'<layer-list xmlns:android="http://schemas.android.com/apk/res/android"><item><shape><size android:width="72dp" android:height="72dp"/><solid android:color="#000000"/></shape></item><item android:width="46.44dp" android:height="46.44dp" android:gravity="center"><bitmap android:src="@drawable/{name}" android:gravity="fill"/></item></layer-list>\n'
  aliases.append(f'        <activity-alias android:enabled="false" android:name="org.telegram.messenger.{key}" android:targetActivity="org.telegram.ui.LaunchActivity" android:label="{brand.capitalize() if brand=="tetogram" else "Mikugram"}" android:icon="@mipmap/{name}" android:roundIcon="@mipmap/{name}" android:exported="true"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter><meta-data android:name="android.app.shortcuts" android:resource="@xml/shortcuts"/></activity-alias>')
 else:
  missing.append(name+'.png');cases.append(f'   case "{key}":return 0; // Missing prepared artwork. Not selectable, no fake icon.')
  aliases.append(f'        <!-- {key}: artwork missing. Prepared component, NOT a launcher entry. -->\n        <activity-alias android:enabled="false" android:name="org.telegram.messenger.{key}" android:targetActivity="org.telegram.ui.LaunchActivity" android:label="{brand.capitalize()}" android:exported="false"/>')
outputs[RES/'values/tetogram_seasonal_icons.xml']='<resources>\n'+'\n'.join(drawables)+'\n</resources>\n'
outputs[ROOT/'TMessagesProj/src/main/java/org/telegram/ui/tetogram/SeasonalIconCatalog.java']='''/* Generated by prepare-seasonal-icons.py. GPL v2 or later. Zero means artwork is absent, not a placeholder. */
package org.telegram.ui.tetogram;
import org.telegram.messenger.R;
import org.telegram.messenger.tetogram.AppearanceIconPolicy;
public final class SeasonalIconCatalog {
 private SeasonalIconCatalog(){}
 public static int resource(String alias){switch(AppearanceIconPolicy.canonical(alias)){
'''+ '\n'.join(cases)+'''\n   default:return 0;
 }}
}
'''
manifest=ROOT/'TMessagesProj/src/main/AndroidManifest.xml';text=manifest.read_text();start='        <!-- Tetogram seasonal aliases:start -->';end='        <!-- Tetogram seasonal aliases:end -->'
assert start in text and end in text,'Seasonal alias generation markers missing'
outputs[manifest]=text.split(start)[0]+start+'\n'+'\n'.join(aliases)+'\n'+end+text.split(end,1)[1]
for path,content in outputs.items():
 data=content if isinstance(content,bytes) else content.encode()
 if args.check:assert path.is_file() and path.read_bytes()==data,f'Stale generated file: {path.relative_to(ROOT)}; run python3 scripts/prepare-seasonal-icons.py'
 elif not path.is_file() or path.read_bytes()!=data:path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
print(f'Seasonal artwork: {len(available)}/8; available: '+', '.join(available))
if missing:print('MISSING prepared source: '+', '.join('assets/launcher/seasonal/'+name for name in missing))
